#define N 1024
int matrix[N][N];
long sum = 0;

// POOR SPATIAL LOCALITY (High Cache Miss Rate)
// Accessing columns (large stride jump)
void bad_locality() {
    for (int j = 0; j < N; j++)
        for (int i = 0; i < N; i++)
            sum += matrix[i][j];
}

// GOOD SPATIAL LOCALITY (Row-Major Access)
// Sequential memory access (Unit stride)
void good_locality() {
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            sum += matrix[i][j];
}
